import{_ as e,o as s,c as t,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const o="/images/admin/login-admin.png",g=JSON.parse('{"title":"1. Cómo Entrar al Panel y Permisos del Equipo","description":"","frontmatter":{},"headers":[],"relativePath":"admin/index.md","filePath":"admin/index.md"}'),i={name:"admin/index.md"};function n(d,a,l,c,p,u){return s(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="_1-como-entrar-al-panel-y-permisos-del-equipo" tabindex="-1">1. Cómo Entrar al Panel y Permisos del Equipo <a class="header-anchor" href="#_1-como-entrar-al-panel-y-permisos-del-equipo" aria-label="Permalink to &quot;1. Cómo Entrar al Panel y Permisos del Equipo&quot;">​</a></h1><p>El <strong>Panel de Administración</strong> es el centro de mando donde los encargados de la tienda, cajeros y personal de bodega gestionan los pedidos, productos, inventario y facturas de la empresa.</p><hr><h2 id="_1-1-¿como-ingresar-al-panel-de-administracion" tabindex="-1">1.1 ¿Cómo ingresar al Panel de Administración? <a class="header-anchor" href="#_1-1-¿como-ingresar-al-panel-de-administracion" aria-label="Permalink to &quot;1.1 ¿Cómo ingresar al Panel de Administración?&quot;">​</a></h2><ul><li><strong>Enlace directo al panel:</strong> <a href="https://pyme.rsfsecure.site/login" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/login</a></li><li>Puedes entrar desde cualquier computadora, tablet o teléfono con conexión a Internet.</li></ul><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Formulario de Inicio de Sesión de la Administración</span><span class="screenshot-url">https://pyme.rsfsecure.site/login</span></div><div class="screenshot-body"><img src="'+o+'" alt="Formulario de Inicio de Sesión de la Administración"></div></div><h3 id="paso-a-paso-para-entrar" tabindex="-1">Paso a paso para entrar: <a class="header-anchor" href="#paso-a-paso-para-entrar" aria-label="Permalink to &quot;Paso a paso para entrar:&quot;">​</a></h3><ol><li>Escribe tu <strong>Correo Electrónico</strong> asignado por la empresa.</li><li>Escribe tu <strong>Contraseña</strong>.</li><li><em>(Opcional)</em> Si la computadora es de tu uso personal, marca la casilla <strong>&quot;Recordarme&quot;</strong> para no tener que escribir tu clave todos los días.</li><li>Haz clic en el botón verde <strong>&quot;Iniciar Sesión&quot;</strong>.</li><li>Al entrar, el sistema te llevará directo a la pantalla principal (<strong>Dashboard</strong>).</li></ol><div class="tip custom-block"><p class="custom-block-title">Nota: ¿Olvidaste tu contraseña?</p><p>Haz clic en el enlace <em>&quot;¿Olvidaste tu contraseña?&quot;</em> debajo del botón. Escribe tu correo y el sistema te enviará un enlace para crear una contraseña nueva de inmediato.</p></div><hr><h2 id="_1-2-¿que-puede-hacer-cada-persona-de-tu-equipo-roles" tabindex="-1">1.2 ¿Qué puede hacer cada persona de tu equipo? (Roles) <a class="header-anchor" href="#_1-2-¿que-puede-hacer-cada-persona-de-tu-equipo-roles" aria-label="Permalink to &quot;1.2 ¿Qué puede hacer cada persona de tu equipo? (Roles)&quot;">​</a></h2><p>Para mantener la seguridad del negocio, cada colaborador tiene acceso únicamente a lo que necesita para su trabajo:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Puesto / Rol</th><th style="text-align:left;">¿A qué tiene acceso?</th><th style="text-align:left;">¿Qué puede hacer?</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Dueño / Super Administrador</strong></td><td style="text-align:left;">Acceso a todo el sistema</td><td style="text-align:left;">Ver ganancias, crear y borrar usuarios, configurar precios, inventario y costos de envío.</td></tr><tr><td style="text-align:left;"><strong>Gerente de Tienda</strong></td><td style="text-align:left;">Ventas, Catálogo e Inventario</td><td style="text-align:left;">Crear y modificar productos, aprobar pedidos, emitir facturas y crear cupones.</td></tr><tr><td style="text-align:left;"><strong>Personal de Bodega / Despacho</strong></td><td style="text-align:left;">Pedidos e Inventario</td><td style="text-align:left;">Ver qué productos hay que empacar, cambiar el estado a &quot;En preparación&quot; o &quot;Enviado&quot; y registrar mercancía nueva.</td></tr><tr><td style="text-align:left;"><strong>Cajero / Facturación</strong></td><td style="text-align:left;">Pedidos y Facturas</td><td style="text-align:left;">Revisar que los depósitos ACH o Yappy hayan entrado e imprimir las facturas y tickets para los paquetes.</td></tr></tbody></table><hr><h2 id="modulos-del-sistema-administrativo" tabindex="-1">Módulos del Sistema Administrativo <a class="header-anchor" href="#modulos-del-sistema-administrativo" aria-label="Permalink to &quot;Módulos del Sistema Administrativo&quot;">​</a></h2><p>Explora las guías paso a paso de cada sección del panel:</p><div class="factus-grid"><a href="/admin/dashboard" class="factus-card"><div class="factus-card-title">2. Dashboard y KPIs de Ventas <span class="arrow">→</span></div><div class="factus-card-desc">Ventas del día en tiempo real, órdenes pendientes y alertas de stock bajo.</div></a><a href="/admin/productos" class="factus-card"><div class="factus-card-title">3. Gestión de Catálogo y Variantes <span class="arrow">→</span></div><div class="factus-card-desc">Publicación de artículos, fotografías HD, precios con 7% ITBMS y tallas.</div></a><a href="/admin/inventario" class="factus-card"><div class="factus-card-title">4. Control de Inventario y Bodega <span class="arrow">→</span></div><div class="factus-card-desc">Kardex de entradas/salidas, recepción de pedidos de proveedores y ajustes.</div></a><a href="/admin/pedidos" class="factus-card"><div class="factus-card-title">5. Flujo y Estados de Pedidos <span class="arrow">→</span></div><div class="factus-card-desc">Aprobación de pagos, empaque de órdenes y generación de guías de envío.</div></a><a href="/admin/facturacion" class="factus-card"><div class="factus-card-title">6. Facturación Fiscal y Anulaciones <span class="arrow">→</span></div><div class="factus-card-desc">Generación de facturas oficiales en PDF, tickets térmicos y notas de crédito.</div></a><a href="/admin/configuracion" class="factus-card"><div class="factus-card-title">7. Envíos por Provincia y Cupones <span class="arrow">→</span></div><div class="factus-card-desc">Tarifas de flete en Panamá, reglas de envío gratis y cupones de descuento.</div></a></div>',17)])])}const f=e(i,[["render",n]]);export{g as __pageData,f as default};
